begin; create extension if not exists pgtap with schema extensions; set search_path=public,extensions; select plan(33);
select has_table('public','contract_materializations','materialization root exists');
select has_column('public','contracts','contract_materialization_id','contract links materialization');
select has_column('public','contracts','source_composition_item_key','contract carries item key');
select has_column('public','contracts','commercial_catalog_code','contract carries catalog code');
select ok(not has_table_privilege('authenticated','public.contract_materializations','INSERT'),'authenticated cannot insert roots');
select ok(not has_table_privilege('authenticated','public.contract_materializations','UPDATE'),'authenticated cannot update roots');
select ok(not has_table_privilege('authenticated','public.contract_materializations','DELETE'),'authenticated cannot delete roots');

insert into public.organizations(id,name,slug) values('a1000000-0000-4000-8000-000000000001','C4 A','c4-a'),('a1000000-0000-4000-8000-000000000002','C4 B','c4-b');
insert into auth.users(id) values('a2000000-0000-4000-8000-000000000001'),('a2000000-0000-4000-8000-000000000002');
insert into public.profiles(id,organization_id,name,email,role) values('a2000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','A','a@c4.test','master'),('a2000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000002','B','b@c4.test','master');
insert into public.crm_leads(id,organization_id,nome) values('a3000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','Lead A'),('a3000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000002','Lead B');
insert into public.clients(id,organization_id,name) values('a4000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','Client A'),('a4000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000002','Client B');
create function pg_temp.c4_snapshot(p_sim text,p_authority text default 'server_derived') returns jsonb language sql as $$select jsonb_build_object('schemaVersion','commercial-proposal/v1','proposalKind','patrimonial_strategy','provenance',jsonb_build_object('authority',p_authority,'simulationId',p_sim,'calculationEngineKey','engine','calculationEngineVersion','1','financialProductKey','product','financialProductVersion','1'),'product',jsonb_build_object('groupCode','2227'),'strategy',jsonb_build_object('quotaCount',1,'totalCredit',jsonb_build_object('amountCents',20000000,'currency','BRL')),'composition',jsonb_build_array(jsonb_build_object('itemKey','item-001','commercialCatalogCode','29.09.5526','credit',jsonb_build_object('amountCents',20000000,'currency','BRL'),'termMonths',216,'installmentPhases',jsonb_build_array(jsonb_build_object('installmentAmount',jsonb_build_object('amountCents',91633,'currency','BRL'))))),'commercialTerms','{}'::jsonb,'disclosures','[]'::jsonb)$$;
select set_config('request.jwt.claim.role','service_role',true);
select public.create_server_derived_patrimonial_proposal_transaction('a1000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001','a5000000-0000-4000-8000-000000000001','a6000000-0000-4000-8000-000000000001','c4-request-a',repeat('a',64),'{"intent":true}','{"result":true}',pg_temp.c4_snapshot('a5000000-0000-4000-8000-000000000001'),public.commercial_proposal_terms_hash(pg_temp.c4_snapshot('a5000000-0000-4000-8000-000000000001')));
select public.create_server_derived_patrimonial_proposal_transaction('a1000000-0000-4000-8000-000000000002','a2000000-0000-4000-8000-000000000002','a3000000-0000-4000-8000-000000000002','a5000000-0000-4000-8000-000000000002','a6000000-0000-4000-8000-000000000002','c4-request-b',repeat('b',64),'{"intent":true}','{"result":true}',pg_temp.c4_snapshot('a5000000-0000-4000-8000-000000000002'),public.commercial_proposal_terms_hash(pg_temp.c4_snapshot('a5000000-0000-4000-8000-000000000002')));
select public.create_server_derived_patrimonial_proposal_transaction('a1000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001','b5000000-0000-4000-8000-000000000003','b6000000-0000-4000-8000-000000000003','c4-request-a2',repeat('c',64),'{"intent":true}','{"result":true}',pg_temp.c4_snapshot('b5000000-0000-4000-8000-000000000003'),public.commercial_proposal_terms_hash(pg_temp.c4_snapshot('b5000000-0000-4000-8000-000000000003')));
create function pg_temp.c4_materialization(p_id uuid,p_org uuid,p_prop uuid,p_sim uuid,p_lead uuid,p_client uuid,p_key text default null) returns void language plpgsql as $$declare s jsonb; p public.crm_lead_commercial_proposals%rowtype; begin select * into p from public.crm_lead_commercial_proposals where id=p_prop; s:=p.saved_snapshot; insert into public.contract_materializations(id,organization_id,source_root_proposal_id,source_proposal_version_id,source_proposal_number,source_proposal_version,source_simulation_id,lead_id,client_id,snapshot_schema_version,snapshot_authority,commercial_terms_hash,composition_hash,materialized_snapshot,item_count,total_credit_amount,idempotency_key,created_by) values(p_id,p_org,p.root_proposal_id,p.id,p.proposal_number,p.version,p_sim,p_lead,p_client,'commercial-proposal/v1','server_derived',public.commercial_proposal_terms_hash(s),public.commercial_proposal_composition_hash(s),s,1,200000,p_key,p.created_by); end $$;
select lives_ok($$select pg_temp.c4_materialization('a7000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','a6000000-0000-4000-8000-000000000001','a5000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001','idem-a')$$,'owner can create structurally valid root');
select throws_ok($$select pg_temp.c4_materialization('a7000000-0000-4000-8000-000000000011','a1000000-0000-4000-8000-000000000001','a6000000-0000-4000-8000-000000000001','a5000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001',null)$$,'23505',null,'one materialization per lineage');
select throws_ok($$select pg_temp.c4_materialization('a7000000-0000-4000-8000-000000000012','a1000000-0000-4000-8000-000000000001','a6000000-0000-4000-8000-000000000002','a5000000-0000-4000-8000-000000000002','a3000000-0000-4000-8000-000000000002','a4000000-0000-4000-8000-000000000001',null)$$,'P0001','CONTRACT_MATERIALIZATION_SOURCE_MISMATCH','cross-tenant proposal fails');
select throws_ok($$insert into public.contract_materializations select 'a7000000-0000-4000-8000-000000000019',organization_id,'b6000000-0000-4000-8000-000000000003',source_proposal_version_id,source_proposal_number,source_proposal_version,source_simulation_id,lead_id,client_id,snapshot_schema_version,snapshot_authority,commercial_terms_hash,composition_hash,materialized_snapshot,item_count,total_credit_amount,null,created_by,now() from public.contract_materializations where id='a7000000-0000-4000-8000-000000000001'$$,'23503',null,'proposal version from another root fails');
select throws_ok($$insert into public.contract_materializations select 'a7000000-0000-4000-8000-000000000013',organization_id,source_root_proposal_id,source_proposal_version_id,source_proposal_number,source_proposal_version,source_simulation_id,lead_id,client_id,'legacy',snapshot_authority,commercial_terms_hash,composition_hash,materialized_snapshot,item_count,total_credit_amount,null,created_by,now() from public.contract_materializations limit 1$$,'P0001','CONTRACT_MATERIALIZATION_SOURCE_MISMATCH','legacy schema fails');
select throws_ok($$insert into public.contract_materializations select 'a7000000-0000-4000-8000-000000000014',organization_id,source_root_proposal_id,source_proposal_version_id,source_proposal_number,source_proposal_version,source_simulation_id,lead_id,client_id,snapshot_schema_version,'client_structured_legacy',commercial_terms_hash,composition_hash,materialized_snapshot,item_count,total_credit_amount,null,created_by,now() from public.contract_materializations limit 1$$,'P0001','CONTRACT_MATERIALIZATION_SOURCE_MISMATCH','ineligible authority fails');
select throws_ok($$insert into public.contract_materializations select 'a7000000-0000-4000-8000-000000000015',organization_id,source_root_proposal_id,source_proposal_version_id,source_proposal_number,source_proposal_version,source_simulation_id,lead_id,client_id,snapshot_schema_version,snapshot_authority,null,composition_hash,materialized_snapshot,item_count,total_credit_amount,null,created_by,now() from public.contract_materializations limit 1$$,'P0001','CONTRACT_MATERIALIZATION_SOURCE_MISMATCH','missing hash fails');
select throws_ok($$insert into public.contract_materializations select 'a7000000-0000-4000-8000-000000000016',organization_id,source_root_proposal_id,source_proposal_version_id,source_proposal_number,source_proposal_version,source_simulation_id,lead_id,client_id,snapshot_schema_version,snapshot_authority,commercial_terms_hash,composition_hash,'[]',item_count,total_credit_amount,null,created_by,now() from public.contract_materializations limit 1$$,'P0001','CONTRACT_MATERIALIZATION_SOURCE_MISMATCH','non-object snapshot fails');
select throws_ok($$insert into public.contract_materializations select 'a7000000-0000-4000-8000-000000000017',organization_id,source_root_proposal_id,source_proposal_version_id,source_proposal_number,source_proposal_version,source_simulation_id,lead_id,client_id,snapshot_schema_version,snapshot_authority,commercial_terms_hash,composition_hash,materialized_snapshot,0,total_credit_amount,null,created_by,now() from public.contract_materializations limit 1$$,'23514',null,'invalid item count fails');
select throws_ok($$insert into public.contract_materializations select 'a7000000-0000-4000-8000-000000000018',organization_id,source_root_proposal_id,source_proposal_version_id,source_proposal_number,source_proposal_version,source_simulation_id,lead_id,client_id,snapshot_schema_version,snapshot_authority,commercial_terms_hash,composition_hash,materialized_snapshot,item_count,0,null,created_by,now() from public.contract_materializations limit 1$$,'23514',null,'invalid total credit fails');
select lives_ok($$select pg_temp.c4_materialization('a7000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000002','a6000000-0000-4000-8000-000000000002','a5000000-0000-4000-8000-000000000002','a3000000-0000-4000-8000-000000000002','a4000000-0000-4000-8000-000000000002','idem-a')$$,'same idempotency key is allowed in another tenant');
select throws_ok($$select pg_temp.c4_materialization('a7000000-0000-4000-8000-000000000003','a1000000-0000-4000-8000-000000000001','b6000000-0000-4000-8000-000000000003','b5000000-0000-4000-8000-000000000003','a3000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001','idem-a')$$,'23505',null,'idempotency key cannot be reused for another lineage in the same tenant');
select lives_ok($$insert into public.contracts(id,organization_id,client_id,status,credit_amount) values('a8000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000001','draft',0)$$,'legacy contract remains valid');
select throws_ok($$insert into public.contracts(id,organization_id,contract_materialization_id,status,credit_amount) values('a8000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000001','a7000000-0000-4000-8000-000000000001','draft',0)$$,'P0001','CONTRACT_MATERIALIZATION_ITEM_INVALID','materialized contract requires item key');
select throws_ok($$insert into public.contracts(id,organization_id,source_composition_item_key,status,credit_amount) values('a8000000-0000-4000-8000-000000000003','a1000000-0000-4000-8000-000000000001','item-001','draft',0)$$,'23514',null,'item key without materialization fails');
select throws_ok($$insert into public.contracts(id,organization_id,contract_materialization_id,source_composition_item_key,status,credit_amount) values('a8000000-0000-4000-8000-000000000006','a1000000-0000-4000-8000-000000000002','a7000000-0000-4000-8000-000000000001','item-001','draft',0)$$,'P0001','CONTRACT_MATERIALIZATION_ITEM_INVALID','cross-tenant materialization link fails');
select lives_ok($$insert into public.contracts(id,organization_id,lead_id,client_id,contract_materialization_id,source_composition_item_key,commercial_catalog_code,contract_group,status,source_proposal_id,source_proposal_version,proposal_snapshot,credit_amount,installment_amount,term_months) select 'a8000000-0000-4000-8000-000000000004',m.organization_id,m.lead_id,m.client_id,m.id,'item-001','29.09.5526','2227','draft',m.source_proposal_version_id,m.source_proposal_version,m.materialized_snapshot#>'{composition,0}',200000,916.33,216 from public.contract_materializations m where id='a7000000-0000-4000-8000-000000000001'$$,'valid draft item contract with null operational identifiers succeeds');
select ok((select contract_number is null and contract_quota is null from public.contracts where id='a8000000-0000-4000-8000-000000000004'),'contract and quota numbers remain nullable');
select throws_ok($$insert into public.contracts(id,organization_id,lead_id,client_id,contract_materialization_id,source_composition_item_key,commercial_catalog_code,contract_group,status,source_proposal_id,source_proposal_version,proposal_snapshot,credit_amount,installment_amount,term_months) select 'a8000000-0000-4000-8000-000000000005',m.organization_id,m.lead_id,m.client_id,m.id,'item-001','29.09.5526','2227','draft',m.source_proposal_version_id,m.source_proposal_version,m.materialized_snapshot#>'{composition,0}',200000,916.33,216 from public.contract_materializations m where id='a7000000-0000-4000-8000-000000000001'$$,'23505',null,'duplicate materialization item fails');
select throws_ok($$update public.contracts set source_composition_item_key='changed' where id='a8000000-0000-4000-8000-000000000004'$$,'P0001','CONTRACT_MATERIALIZATION_ITEM_IMMUTABLE','item identity is immutable');
select throws_ok($$update public.contracts set contract_materialization_id=null where id='a8000000-0000-4000-8000-000000000004'$$,'P0001','CONTRACT_MATERIALIZATION_ITEM_IMMUTABLE','materialization link is immutable');
select throws_ok($$update public.contract_materializations set item_count=2 where id='a7000000-0000-4000-8000-000000000001'$$,'P0001','CONTRACT_MATERIALIZATION_IMMUTABLE','root is append-only');
select throws_ok($$delete from public.contract_materializations where id='a7000000-0000-4000-8000-000000000001'$$,'P0001','CONTRACT_MATERIALIZATION_IMMUTABLE','root deletion is blocked');
select set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000001',true); set local role authenticated;
select is((select count(*)::integer from public.contract_materializations where organization_id='a1000000-0000-4000-8000-000000000002'),0,'tenant cannot read foreign root');
select throws_ok($$insert into public.contract_materializations(id) values(gen_random_uuid())$$,'42501',null,'authenticated direct root insert denied');
reset role;
select is((select count(*)::integer from public.contracts where source_proposal_id is not null and contract_materialization_id is null),0,'clean baseline has no legacy proposal-linked contracts');
select * from finish(); rollback;
